from pathlib import Path
import csv
R=Path(__file__).resolve().parents[2];O=R/'docs/audits'
update='''
## Additional executed acceptance: export and source recovery

After the earlier checkpoint, real HTTP case export uncovered two integration defects: CaseError/ExportError were not registered with the application error mapper (not-ready export answered 500), and approval API approve/deny/revoke did not call the existing export-job transition hook. app.main now registers the existing domain response mapping; app.api.unblur connects on_approval_decided. No policy was bypassed. The expanded real-model test adds a case observation, records the fixture's explicit CC BY 3.0 license through the existing admin grant API, requests export, observes not-ready 409, obtains independent admin approval, generates/downloads the encrypted package through signed authenticated access, and verifies the canonical manifest digest and all member hashes using verify_package. Package remains unsigned: hash integrity is not independent legal custody. **14 passed in 17.29 s** with the approvals suite (case-export-release.log).

The managed test now forcibly interrupts only sockets belonging to its controlled replay server and temporarily refuses reconnection. It observes authoritative reconnecting health, expiry of stale preview (404), restoration of actual frames and healthy state, then stops the worker on disable. **1 passed in 14.70 s** (managed-recovery.log). This does not establish external-live availability or multi-camera capacity. Approved configuration state is still fixture-created; actual two-admin UI activation and revision change remain unverified.

The full original-suite checkpoint was 419 passed + 2 skipped; backend-final-proof.log is the subsequent full run including these added assertions. Consult its final summary before using it as release evidence. Docs checker now works without Git metadata; snapshot omissions and quoted relative links were corrected, with 0 broken links in 85 Markdown files at that checkpoint. README source snapshot is README_BEFORE_SOURCE.txt.
'''
for name in ['POST_INTEGRATION_README_AUDIT_AFTER.md','TEST_EXECUTION_LEDGER.md','FINAL_ENGINEERING_HANDOFF.md','SECURITY_PRIVACY_REGRESSION.md','ISSUES_AND_UNVERIFIED_EVIDENCE.md']:
 p=O/name;p.write_text(p.read_text()+update)
p=O/'ISSUES_AND_UNVERIFIED_EVIDENCE.md';s=p.read_text().replace('- Forced source outage/reconnect, effective approved reconfiguration, multi-camera load/soak and restart durability remain incomplete.','- Controlled local source outage/reconnect has passed. Effective approved reconfiguration, multi-camera load/soak and restart durability remain incomplete.').replace('- No actual case-package download/manifest/signature validation for promoted incident; code imported is not proof.','- Actual promoted case-package download and SHA-256 manifest/member validation passed. Package is unsigned; independent signature/custody is not claimed.');p.write_text(s)
p=O/'TOP_TWO_FEATURE_ACCEPTANCE.md';s=p.read_text().replace('F1-05 UNVERIFIED: approved case export manifest and crash/restart durability.','F1-05 PASS EXPORT: real HTTP case note, explicit license grant, independent approval, signed download and offline manifest/member hash verification. Package unsigned. Crash/restart durability remains UNVERIFIED.').replace('F2-04 UNVERIFIED: forced disconnect and reconnect, approved effective config reload/rollback, multi-camera stress and live detail browser.','F2-04 PASS LOCAL RECOVERY: source socket disruption -> reconnecting -> preview expires -> recovered frames. Approved config reload/rollback, multi-camera stress and live detail browser remain UNVERIFIED.').replace('F2-05 UNVERIFIED: eligible model-derived live incident + exported evidence. Recorded positive and HMAC ingest are separate verified components, not a claimed single live incident test.','F2-05 UNVERIFIED: eligible model-derived live incident with approved export; recorded positive + exported package and signed live replay remain separately verified components.');p.write_text(s)
p=R/'docs/implementation/FEATURE_01_AI_INCIDENT_TO_OPERATOR.md';s=p.read_text().replace('approval/export hash proof for a promoted alert; ', 'broader export-revocation and package-tamper negatives; ');p.write_text(s+update)
p=R/'docs/implementation/FEATURE_02_AUTHORIZED_LIVE_CAMERA.md';s=p.read_text().replace('supervised reconnect/backoff during forced outage, ', 'longer reconnect/soak coverage beyond the passed controlled interruption, ');p.write_text(s+update)
p=O/'REMAINING_FEATURES_MASTER_BACKLOG.md';s=p.read_text().replace('Promote a model-derived candidate, create note/bookmark/legal hold, obtain required independent approval, download package and verify every hash/manifest with negative permissions.','Basic promoted-candidate note/license-grant/independent-approval/package/hash path now passes. Next add bookmarks, legal hold, grant revocation, tamper negatives and browser export.').replace('Interrupt and restore a test-owned MJPEG source; assert degraded/offline/recovered states, bounded threads, queues, memory and no duplicate evidence across two cameras.','Single-source interruption/reconnecting/expired-preview/recovery now passes. Next measure bounded threads, queues, memory and duplicate evidence across two cameras and a longer outage.').replace('Approval-to-export manifest verification of promoted incident not proven in this mission.','Basic promoted-incident export and manifest verification passed; broader revocation/hold/browser cases remain.');p.write_text(s)
with (O/'README_COVERAGE_MATRIX.csv').open() as f:rows=list(csv.DictReader(f));fields=list(rows[0])
for r in rows:
 if r['id']=='A15':r['evidence_link']='case-export-release.log';r['next_acceptance']='Basic case-note/license-grant/four-eyes export/hash verification passed; next bookmark, legal hold, revoked grant, tampering and browser export.'
 if r['id']=='A24':r['evidence_link']='managed-recovery.log';r['next_acceptance']='Local recovery and disable passed; next actual UI approval/config change, live detail browser and multi-camera soak.'
with (O/'README_COVERAGE_MATRIX.csv').open('w') as f:w=csv.DictWriter(f,fieldnames=fields);w.writeheader();w.writerows(rows)
